structure.mermaidSource:
flowchart TD
  start["Início: Traçar Seta de Modificação"] --> proc_alvo["Classificar Termo-Alvo"]
  proc_alvo --> dec_alvo{"Termo-alvo é Verbo, Adjetivo ou Advérbio?"}
  dec_alvo -- "Sim (Verbo/Adjetivo/Advérbio)" --> res_adverbio["Resultado: ADVÉRBIO"]
  dec_alvo -- "Não (Substantivo)" --> proc_desempate["Desempate Nominal: Adjetivo vs. Pronome"]
  proc_desempate --> dec_suficiente{"Aceita substituição por 'suficiente(s)'?"}
  dec_suficiente -- "Sim (Qualifica / Posposto)" --> res_adjetivo["Resultado: ADJETIVO"]
  dec_suficiente -- "Não" --> dec_muito{"Aceita substituição por 'muito(s)/muita(s)'?"}
  dec_muito -- "Sim (Quantifica / Anteposto)" --> res_pron_indef["Resultado: PRONOME INDEFINIDO ADJETIVO"]
  dec_muito -- "Não" --> res_outro_nominal["Resultado: Outro Determinante / Reavaliar"]

flowchart TD
  start["Início: Análise de 'Todo / Toda'"] --> dec_artigo{"Há artigo definido logo após?\n(todo o / toda a)}
  dec_artigo -- "Sim" --> dec_inteiro{"Admite substituição por\n'inteiro(a)'?}
  dec_inteiro -- "Sim" --> res_totalidade["Sentido de Totalidade / Integridade\n(Ex.: Toda a cidade = A cidade inteira)"]
  dec_inteiro -- "Não" --> res_reavaliar["Reavaliar contexto e estrutura sintática"]
  dec_artigo -- "Não" --> dec_unitario{"Substantivo é unitário / indivisível?\n(Filtro CESPE: ex.: 'todo mundo')}
  dec_unitario -- "Sim" --> res_total_cespe["Sentido de Totalidade\n(Mesmo sem artigo)"]
  dec_unitario -- "Não" --> dec_qualquer{"Admite substituição por\n'qualquer'?}
  dec_qualquer -- "Sim" --> res_generico["Sentido Genérico / Distributivo\n(Ex.: Toda operação = Qualquer operação)"]
  dec_qualquer -- "Não" --> res_reavaliar
